static zum_estado zum_estado_{PIN};

ZUM_MELODIAS = (
    ((523, 100), (659, 100), (784, 100), (1047, 160)),
    ((659, 100), (784, 100), (1047, 140), (1319, 180)),
    ((392, 120), (330, 120), (262, 120), (196, 220)),
    ((880, 100), (440, 100), (880, 100), (440, 100), (880, 100), (440, 180)),
)
ZUM_TIC_MS = 10
# Por pin: [PWM, notas que faltan o None, índice, ms que le quedan a la nota, tono continuo].
zum_estados = {}
zum_reloj = None

def zum_estado(pin):
    if pin not in zum_estados:
        zum_estados[pin] = [PWM(Pin(pin), freq=440, duty_u16=0), None, 0, 0, False]
    return zum_estados[pin]

def zum_sonar(pwm, hz):
    pwm.freq(int(hz))
    pwm.duty_u16(32768)

def zum_callar(estado):
    estado[0].duty_u16(0)
    estado[1] = None
    estado[4] = False

# Corre cada 10 ms con un Timer: avanza las notas sin frenar el programa.
def zum_tic(_):
    for estado in zum_estados.values():
        if estado[1] is None:
            continue
        estado[3] -= ZUM_TIC_MS
        if estado[3] > 0:
            continue
        estado[2] += 1
        if estado[2] >= len(estado[1]):
            zum_callar(estado)
        else:
            hz, ms = estado[1][estado[2]]
            zum_sonar(estado[0], hz)
            estado[3] = ms

def zum_empezar(pin, notas):
    global zum_reloj
    estado = zum_estado(pin)
    estado[1] = None
    estado[2] = 0
    estado[3] = notas[0][1]
    estado[4] = False
    zum_sonar(estado[0], notas[0][0])
    estado[1] = notas
    if zum_reloj is None:
        zum_reloj = Timer(0)
        zum_reloj.init(period=ZUM_TIC_MS, mode=Timer.PERIODIC, callback=zum_tic)

def zum_tono(pin, hz, bloque):
    hz = rb_finite(hz, bloque)
    if not 31 <= hz <= 20000:
        rb_fail(bloque, "La frecuencia debe estar entre 31 y 20000 Hz")
    estado = zum_estado(pin)
    estado[1] = None
    estado[4] = True
    zum_sonar(estado[0], hz)

def zum_nota(pin, hz, ms, bloque):
    ms = rb_finite(ms, bloque)
    if not 0 <= ms <= 60000:
        rb_fail(bloque, "La duración debe estar entre 0 y 60000 ms")
    zum_empezar(pin, ((hz, ms),))

def zum_detener(pin):
    zum_callar(zum_estado(pin))

def zum_sonando(pin):
    estado = zum_estados.get(pin)
    return estado is not None and (estado[4] or estado[1] is not None)

struct zum_nota { uint16_t hz; uint16_t ms; };
static const zum_nota zum_melodias[4][6] = {
    {{523, 100}, {659, 100}, {784, 100}, {1047, 160}},
    {{659, 100}, {784, 100}, {1047, 140}, {1319, 180}},
    {{392, 120}, {330, 120}, {262, 120}, {196, 220}},
    {{880, 100}, {440, 100}, {880, 100}, {440, 100}, {880, 100}, {440, 180}},
};
static const uint8_t zum_largos[4] = { 4, 4, 4, 6 };
struct zum_estado {
    const zum_nota* notas = nullptr;
    uint8_t indice = 0, cantidad = 0;
    uint32_t inicio = 0;
    zum_nota unica = {0, 0};
    bool continuo = false;
};
inline int zum_numero(const String& texto) {
    return atoi(texto.c_str());
}
inline void zum_detener(zum_estado& estado, int pin) {
    estado.notas = nullptr;
    estado.continuo = false;
    noTone(pin);
}
inline void zum_empezar(zum_estado& estado, int pin, const zum_nota* notas, uint8_t cantidad) {
    estado.notas = notas;
    estado.cantidad = cantidad;
    estado.indice = 0;
    estado.continuo = false;
    estado.inicio = millis();
    tone(pin, notas[0].hz);
}
inline void zum_tono(zum_estado& estado, int pin, float hz, const char* bloque) {
    hz = rb_finite(hz, bloque);
    if (rb_failed) return;
    if (!(hz >= 31 && hz <= 20000)) {
        rb_fail(bloque, "La frecuencia debe estar entre 31 y 20000 Hz");
        return;
    }
    estado.notas = nullptr;
    estado.continuo = true;
    tone(pin, (unsigned int)hz);
}
inline void zum_nota_iniciar(zum_estado& estado, int pin, int hz, float ms, const char* bloque) {
    ms = rb_finite(ms, bloque);
    if (rb_failed) return;
    if (!(ms >= 0 && ms <= 60000)) {
        rb_fail(bloque, "La duración debe estar entre 0 y 60000 ms");
        return;
    }
    estado.unica.hz = uint16_t(hz);
    estado.unica.ms = uint16_t(ms);
    zum_empezar(estado, pin, &estado.unica, 1);
}
inline void zum_melodia(zum_estado& estado, int pin, int indice) {
    zum_empezar(estado, pin, zum_melodias[indice], zum_largos[indice]);
}
// Se llama en cada vuelta (poll): cambia de nota cuando se cumple su tiempo.
inline void zum_paso(zum_estado& estado, int pin) {
    if (!estado.notas) return;
    if (uint32_t(millis() - estado.inicio) < estado.notas[estado.indice].ms) return;
    if (++estado.indice >= estado.cantidad) {
        zum_detener(estado, pin);
        return;
    }
    estado.inicio = millis();
    tone(pin, estado.notas[estado.indice].hz);
}
inline bool zum_sonando(const zum_estado& estado) {
    return estado.continuo || estado.notas != nullptr;
}
static zum_estado zum_estado_{PIN};
